  JOIN tasks t ON t.id = trp.subject_id
  WHERE t.label LIKE '%legacy%cutover%' OR t.id LIKE '%legacy-cutover%'
),
target_deployment AS (
  SELECT ttd.object_id AS deployment_id
  FROM task_targets_deployment ttd
  JOIN tasks t ON t.id = ttd.subject_id
  WHERE t.label LIKE '%legacy%cutover%' OR t.id LIKE '%legacy-cutover%'
),
affected_modules AS (
  SELECT mdp.subject_id AS module_id
  FROM module_depends_on_package mdp
  JOIN retiring r ON r.package_id = mdp.object_id
  UNION
  SELECT mdm.subject_id AS module_id
  FROM module_depends_on_module mdm
  JOIN affected_modules am ON am.module_id = mdm.object_id
)
SELECT DISTINCT s.id
FROM services s
JOIN service_implements_module sim ON sim.subject_id = s.id
JOIN affected_modules am ON am.module_id = sim.object_id
JOIN service_deployed_to_deployment sdd ON sdd.subject_id = s.id
JOIN target_deployment td ON td.deployment_id = sdd.object_id
ORDER BY s.id
"""

covered_sql = """
WITH RECURSIVE retiring AS (
