),
target_deployment AS (
  SELECT ttd.object_id AS deployment_id
  FROM task_targets_deployment ttd
  JOIN tasks t ON t.id = ttd.subject_id
  WHERE t.label LIKE '%legacy%cutover%' OR t.id LIKE '%legacy-cutover%'
),
affected_modules AS (
  SELECT mdp.subject_id AS module_id
  FROM module_depends_on_package mdp
